const cutoff = Date.now() - 26 * 3600 * 1000;
const items = $input.all()
  .map(i => i.json)
  .filter(j => j.link && j.title && new Date(j.isoDate || j.pubDate || 0).getTime() >= cutoff)
  .filter(j => !/\/(live|video|audio|gallery|ng-interactive|picture|membership)\//.test(j.link))
  .slice(0, 8);
return items.map(j => ({ json: { title: j.title, link: j.link.split('?')[0] } }));

const meta = $('Guardian Filter').item.json;
const html = $json.data;
if (typeof html !== 'string' || !html) return null;
const strip = s => s.replace(/<[^>]*>/g, ' ');
const dec = s => s.replace(/&amp;/g, '&').replace(/&lt;/g, '<').replace(/&gt;/g, '>')
  .replace(/&quot;/g, '"').replace(/&#x27;|&#39;/g, "'").replace(/&nbsp;/g, ' ')
  .replace(/\s+/g, ' ').trim();
const junk = /^(Sign up|Follow |Read more|Related|Advertisement|Reuse this content|Share$|Topics$)/i;
const grab = (seg, re) => {
  const out = [];
  let m;
  while ((m = re.exec(seg)) !== null) {
    const t = dec(strip(m[1]));
    if (t && !junk.test(t)) out.push(t);
  }
  return out;
};
const pRe = () => /<p[^>]*>([\s\S]*?)<\/p>/g;
let text = '';
// 方法1：JSON-LD 的 articleBody（若頁面有提供）
for (const m of html.matchAll(/<script[^>]*application\/ld\+json[^>]*>([\s\S]*?)<\/script>/g)) {
  try {
    const j = JSON.parse(m[1]);
    for (const o of (Array.isArray(j) ? j : [j])) {
      if (o && typeof o.articleBody === 'string' && o.articleBody.trim().length > text.length) text = o.articleBody.trim();
    }
  } catch (e) {}
}
// 方法2：內文區塊（data-gu-name="body" 或 #maincontent）
if (text.length < 300) {
  let seg = '';
  const i = html.indexOf('data-gu-name="body"');
  if (i >= 0) seg = html.slice(i);
  else { const k = html.indexOf('id="maincontent"'); if (k >= 0) seg = html.slice(k); }
  const e = seg.indexOf('</article>');
  if (e > 0) seg = seg.slice(0, e);
  text = grab(seg, pRe()).filter(t => t.length >= 40).join('\n');
}
// 方法3：<article> 內較長的段落
if (text.length < 300) {
  const a = html.match(/<article[\s\S]*?<\/article>/i);
  if (a) text = grab(a[0], pRe()).filter(t => t.length >= 60).join('\n');
}
// 方法4：最後手段，整頁較長的段落
if (text.length < 300) text = grab(html, pRe()).filter(t => t.length >= 80).join('\n');
if (!text) return null;
return { source: 'The Guardian', title: meta.title, link: meta.link, text };

const cutoff = Date.now() - 26 * 3600 * 1000;
const items = $input.all()
  .map(i => i.json)
  .filter(j => j.link && j.title && new Date(j.isoDate || j.pubDate || 0).getTime() >= cutoff)
  .filter(j => /\/news\/(articles|world)/.test(j.link))
  .slice(0, 8);
return items.map(j => ({ json: { title: j.title, link: j.link } }));

const meta = $('BBC Filter').item.json;
const html = $json.data;
if (typeof html !== 'string' || !html) return null;
const strip = s => s.replace(/<[^>]*>/g, ' ');
const dec = s => s.replace(/&amp;/g, '&').replace(/&lt;/g, '<').replace(/&gt;/g, '>')
  .replace(/&quot;/g, '"').replace(/&#x27;|&#39;/g, "'").replace(/&nbsp;/g, ' ')
  .replace(/\s+/g, ' ').trim();
const junk = /This video can not be played|To play this video/i;
const grab = (seg, re) => {
  const out = [];
  let m;
  while ((m = re.exec(seg)) !== null) {
    const t = dec(strip(m[1]));
    if (t && !junk.test(t)) out.push(t);
  }
  return out;
};
const art = (html.match(/<article[\s\S]*?<\/article>/i) || [html])[0];
// 方法1：<article> 內 class 含 Paragraph 的段落（BBC 目前的版面）
let paras = grab(art, /<p[^>]*class="[^"]*Paragraph[^"]*"[^>]*>([\s\S]*?)<\/p>/g);
// 方法2：舊版 text-block 區塊
if (paras.join('').length < 300) {
  paras = [];
  for (const part of html.split('data-component="text-block"').slice(1)) {
    paras.push(...grab(part.split(/data-component="/)[0], /<p[^>]*>([\s\S]*?)<\/p>/g));
  }
}
// 方法3：<article> 內較長的 <p>
if (paras.join('').length < 300) paras = grab(art, /<p[^>]*>([\s\S]*?)<\/p>/g).filter(t => t.length >= 60);
// 方法4：最後手段，整頁較長的段落
if (paras.join('').length < 300) paras = grab(html, /<p[^>]*>([\s\S]*?)<\/p>/g).filter(t => t.length >= 80);
const text = paras.join('\n');
if (!text) return null;
return { source: 'BBC', title: meta.title, link: meta.link, text };

const md = $input.first().json.data;
if (typeof md !== 'string') return [];
const fmt = d => `${d.getUTCFullYear()}/${String(d.getUTCMonth() + 1).padStart(2, '0')}/${String(d.getUTCDate()).padStart(2, '0')}`;
const now = Date.now();
// CNN 網址的日期是美國時間：收 UTC 昨天、UTC 今天、台北今天，再靠去重避免重複
const days = new Set([fmt(new Date(now - 86400000)), fmt(new Date(now)), fmt(new Date(now + 8 * 3600000))]);
const exclude = /\/(live-news|videos?|interactive|gallery|audio)\//;
const re = /\]\((https:\/\/(?:edition|www)\.cnn\.com\/(\d{4}\/\d{2}\/\d{2})\/[^)\s#?]+)/g;
const seen = new Set();
const out = [];
let m;
while ((m = re.exec(md)) !== null) {
  const link = m[1];
  if (!days.has(m[2]) || exclude.test(link) || seen.has(link)) continue;
  seen.add(link);
  out.push({ json: { link } });
  if (out.length >= 8) break;
}
return out;

const meta = $('CNN Links').item.json;
const raw = $json.data;
if (typeof raw !== 'string' || !raw) return null;
let title = '', body = raw;
try {
  const j = JSON.parse(raw);
  if (j && j.data) { title = j.data.title || ''; body = j.data.content || j.data.text || ''; }
} catch (e) {
  const tm = raw.match(/^Title:\s*(.+)$/m);
  if (tm) title = tm[1];
  const cm = raw.match(/^\w+ Content:\s*$/m);
  body = cm ? raw.slice(raw.indexOf(cm[0]) + cm[0].length) : raw;
}
title = String(title).replace(/\s*\|\s*CNN.*$/i, '').trim();
if (!title) {
  // 沒有標題時，用網址最後的 slug 當備用，絕不使用完整網址
  const seg = meta.link.split('/').filter(Boolean).slice(-2)[0] || '';
  title = decodeURIComponent(seg).replace(/-/g, ' ').replace(/^\w/, c => c.toUpperCase());
}
body = body.replace(/!\[[^\]]*\]\([^)]*\)/g, '').replace(/\[([^\]]+)\]\([^)]*\)/g, '$1');
const lines = body.split('\n').map(l => l.trim())
  .filter(l => l.length >= 60 && !/^(#|\*|-|>|Image|Sign up|Read more|Watch|Copyright|©|Follow)/i.test(l));
const text = lines.join('\n');
if (!text) return null;
return { source: 'CNN', title, link: meta.link, text };

const MIN_LEN = 400, MAX_LEN = 4000, PER_SOURCE = 3, MAX_TOTAL = 9;
const seen = new Set();
const count = {};
const out = [];
for (const it of $input.all()) {
  const j = it.json;
  if (!j.text || j.text.length < MIN_LEN) continue;
  const key = String(j.title).toLowerCase().replace(/[^a-z0-9]/g, '');
  if (seen.has(key)) continue;
  count[j.source] = (count[j.source] || 0);
  if (count[j.source] >= PER_SOURCE) continue;
  seen.add(key);
  count[j.source]++;
  out.push({ json: { source: j.source, title: j.title, link: j.link, text: j.text.slice(0, MAX_LEN) } });
  if (out.length >= MAX_TOTAL) break;
}
return out;

